/**
 * Dataset.
 *
 * What is mounted, counted rather than declared. Every figure on this page -
 * files, rows, valid rows, blank fields, sampling rate, label distribution -
 * is read off the filesystem by the backend when the page loads. Nothing here
 * is a constant, and a corpus that is not present says so instead of showing
 * a plausible number.
 *
 * The two things it is most careful about are the two easiest to get wrong:
 *
 *   PROVENANCE   this corpus is generated by a documented simulator, so it is
 *                tagged SIMULATED everywhere and never called measured.
 *   CAPABILITY   it carries one bulk engine temperature, not eight cylinder
 *                thermocouples, so cylinder-level localisation cannot run on
 *                it. That gap is listed, not quietly filled in.
 */

import { useCallback, useEffect, useState } from 'react'
import { Database, Play, RefreshCw, RotateCcw } from 'lucide-react'
import { api } from '../services/api'
import { liveOrSnapshot } from '../services/reports'
import { useTwin } from '../store/useTwin'
import {
  Badge, Empty, Loading, Metrics, Note, PageHead, StatusRows, TagRow, fmt,
} from '../components/ui/Primitives'

type Report = any

export default function Dataset() {
  const [report, setReport] = useState<Report | null>(null)
  /* null means 'not fetched yet' as well as 'not available', and the two must
     not look the same on screen. */
  const [loaded, setLoaded] = useState(false)
  const [busy, setBusy] = useState<string | null>(null)
  const refreshStatus = useTwin((s) => s.refreshStatus)
  const mode = useTwin((s) => s.mode)

  const load = useCallback(async () => {
    // The backend counts the corpus live. Where there is no backend - the
    // console served as a static bundle - the same report, produced by the
    // same function at build time, ships as a file beside the app. The figures
    // are the same; only when they were counted differs, and the page says so.
    const next = await liveOrSnapshot(api.datasetStatus, 'dataset')
    if (next) setReport(next)
    setLoaded(true)
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  /** Replaying a file through the twin needs a running twin. */
  const canReplay = !report?.snapshot

  const activate = async (file?: string) => {
    setBusy(file ?? 'restore')
    if (file) await api.datasetActivate(file)
    else await api.datasetRestore()
    await load()
    await refreshStatus()
    setBusy(null)
  }

  if (!loaded) return <Loading height={280} />

  if (!report) {
    return (
      <>
        <PageHead title="Dataset" />
        <Empty
          label="NO CORPUS REPORT"
          detail={
            mode === 'DEMO'
              ? 'No ground station is answering and no build-time report shipped with this bundle. Run the backend, or generate one with python -m tools.export_dataset_report.'
              : 'Could not reach the ground station.'
          }
        />
      </>
    )
  }

  const files: any[] = report.files ?? []
  const mapped: any[] = report.mapped ?? []
  const unsupported: any[] = report.unsupported ?? []
  /* Read off the backend's own capability report rather than restated here, so
     the badge cannot claim a coverage the diagnosis engine does not have. */
  const perCylinder = !unsupported.some((u: any) => /^(cht|egt)_\d$/.test(String(u.channel)))
  const labels: Record<string, number> = report.labels ?? {}
  const states: Record<string, number> = report.states ?? {}
  const mounted: boolean = !!report.mounted

  const tone =
    report.status === 'READY' ? 'ok'
      : report.status === 'WARNING' ? 'caution'
        : report.status === 'UNAVAILABLE' ? 'caution' : 'crit'

  return (
    <>
      <PageHead
        title="Dataset"
        actions={
          <div className="row row--tight">
            <Badge tone="sim">{report.provenance}</Badge>
            <Badge tone={tone} dot live={report.status === 'READY'}>{report.status}</Badge>
            {report.snapshot
              ? <Badge tone="caution">BUILD SNAPSHOT</Badge>
              : <Badge tone="ok">LIVE COUNT</Badge>}
            {report.active && <Badge tone="info" dot live>ON THE LIVE SEAT</Badge>}
            <button className="btn btn--sm" onClick={() => void load()}>
              <RefreshCw size={12} /> RESCAN
            </button>
          </div>
        }
      />

      {/* ---- what is mounted --------------------------------------------- */}
      <section className="panel panel--marked" style={{ marginBottom: 16 }}>
        <header className="panel__head">
          <Database size={13} color="var(--accent-ink)" />
          <h2 className="panel__title">Corpus</h2>
          <span className="panel__spacer" />
          <span className="micro">{report.reference}</span>
        </header>
        <div className="panel__body">
          {!mounted ? (
            <Empty
              label="CORPUS NOT PRESENT"
              detail={`No CSV files under ${report.directory}. Set ${report.env_var} to point at a copy.`}
            />
          ) : (
            <>
              <Metrics
                cells={[
                  { k: 'FILES', v: String(report.file_count) },
                  { k: 'ROWS', v: Number(report.rows).toLocaleString() },
                  { k: 'VALID', v: Number(report.valid_rows).toLocaleString() },
                  { k: 'INVALID', v: String(report.invalid_rows), tone: report.invalid_rows ? 'caution' : undefined },
                  { k: 'BLANKS', v: String(report.missing_values) },
                  { k: 'RATE', v: report.sample_rate_hz ? fmt(report.sample_rate_hz, 2) : '—', unit: 'Hz' },
                  { k: 'SIGNALS', v: String(report.signals) },
                ]}
              />
              {report.snapshot && (
                <Note tone="warn">
                  Counted at build time ({String(report.generated_at).replace('T', ' ').replace('+00:00', ' UTC')}),
                  not just now: no ground station is answering. Run the backend for a live count and to replay a
                  file through the twin.
                </Note>
              )}
            </>
          )}
        </div>
      </section>

      <div className="grid grid--2" style={{ marginBottom: 16 }}>
        {/* ---- per file -------------------------------------------------- */}
        <section className="panel">
          <header className="panel__head">
            <h2 className="panel__title">Corpus files</h2>
          </header>
          <div className="panel__body panel__body--tight">
            <table className="table">
              <thead>
                <tr>
                  <th>FILE</th>
                  <th className="num">ROWS</th>
                  <th className="num">RATE</th>
                  <th className="num">SPAN</th>
                  <th>STATE</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {files.map((f) => (
                  <tr key={f.name}>
                    <td className="strong">{f.name}</td>
                    <td className="num">{Number(f.rows).toLocaleString()}</td>
                    <td className="num">{f.sample_rate_hz ? `${fmt(f.sample_rate_hz, 2)} Hz` : '—'}</td>
                    <td className="num">{f.duration_s ? `${Math.round(f.duration_s)} s` : '—'}</td>
                    <td>
                      <Badge tone={f.status === 'PASS' ? 'ok' : f.status === 'WARNING' ? 'caution' : 'crit'}>
                        {f.status}
                      </Badge>
                    </td>
                    <td>
                      <button
                        className="btn btn--sm"
                        disabled={busy !== null || !canReplay}
                        title={canReplay
                          ? 'Replay this file through the twin'
                          : 'Replaying a corpus needs the ground-station backend'}
                        onClick={() => void activate(f.name.replace(/\.csv$/, ''))}
                      >
                        <Play size={11} /> REPLAY
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {report.active && (
              <button
                className="btn btn--sm"
                style={{ marginTop: 10 }}
                disabled={busy !== null}
                onClick={() => void activate()}
              >
                <RotateCcw size={11} /> RETURN TO DEMONSTRATION SOURCE
              </button>
            )}
          </div>
        </section>

        {/* ---- labels ---------------------------------------------------- */}
        <section className="panel">
          <header className="panel__head">
            <h2 className="panel__title">Ground truth</h2>
            <span className="panel__spacer" />
            <span className="micro">GENERATOR LABELS · NOT MAINTENANCE FINDINGS</span>
          </header>
          <div className="panel__body panel__body--tight">
            <StatusRows
              rows={Object.entries(labels).map(([key, count]) => ({
                k: key,
                v: `${count.toLocaleString()} rows`,
                tone: key === 'NONE' ? 'ok' : 'caution',
              }))}
            />
            <div className="divider" />
            {Object.entries(states).map(([state, count]) => (
              <TagRow
                key={state}
                label={state}
                state={`${count.toLocaleString()}`}
                tone={state === 'NORMAL' ? 'ok' : state === 'FAULT' ? 'crit' : 'caution'}
                meta="ROWS"
              />
            ))}
          </div>
        </section>
      </div>

      <div className="grid grid--2">
        {/* ---- channel mapping ------------------------------------------- */}
        <section className="panel">
          <header className="panel__head">
            <h2 className="panel__title">Channel mapping</h2>
            <span className="panel__spacer" />
            <span className="micro">SOURCE → AEROTWIN</span>
          </header>
          <div className="panel__body panel__body--tight">
            <table className="table">
              <thead>
                <tr>
                  <th>SOURCE</th>
                  <th>UNIT</th>
                  <th>CHANNEL</th>
                  <th>UNIT</th>
                  <th className="num">×</th>
                </tr>
              </thead>
              <tbody>
                {mapped.map((m) => (
                  <tr key={m.source} title={m.note}>
                    <td className="strong">{m.source}</td>
                    <td className="dim">{m.source_unit}</td>
                    <td className="strong">{m.target}</td>
                    <td className="dim">{m.target_unit}</td>
                    <td className="num">{m.factor === 1 ? '—' : fmt(m.factor, 4)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        {/*
          What this corpus supports diagnostically.

          This replaced a list of every absent channel with its schema reason -
          eleven rows of column names, which told an operator nothing they could
          act on and told everyone else that they were looking at a research
          tool. The fact that actually matters is whether a finding can be
          attributed to a cylinder, and that is one line. The channel-level
          detail is still published by the backend and still gates the
          diagnosis; it is simply not the operator's problem.
        */}
        <section className="panel">
          <header className="panel__head">
            <h2 className="panel__title">Diagnostic coverage</h2>
            <span className="panel__spacer" />
            <Badge tone={perCylinder ? 'ok' : 'caution'}>
              {perCylinder ? 'PER-CYLINDER' : 'ENGINE LEVEL'}
            </Badge>
          </header>
          <div className="panel__body">
            <StatusRows
              rows={[
                { k: 'MAPPED SIGNALS', v: String(report.signals) },
                { k: 'ENGINE-LEVEL DIAGNOSIS', v: 'AVAILABLE', tone: 'ok' },
                {
                  k: 'CYLINDER ATTRIBUTION',
                  v: perCylinder ? 'AVAILABLE' : 'UNAVAILABLE',
                  tone: perCylinder ? 'ok' : 'caution',
                },
              ]}
            />
            <Note tone={perCylinder ? 'info' : 'warn'}>
              {perCylinder
                ? 'Per-cylinder head and exhaust temperatures are present, so a deviation can be attributed to a cylinder.'
                : 'This corpus carries a single engine temperature rather than one per cylinder, so findings are reported at engine level. Attributing one to a cylinder needs four head and four exhaust probes.'}
            </Note>
          </div>
        </section>
      </div>
    </>
  )
}
